// Player numbers own magic/run aliases; the selected logical device owns
// movement/attack/jump. Keep the help consistent when Options swaps devices.
export function playerControls(index,device='keypad',players=1) {
  const p1=index===0,keyboard=['keypad','keyboard'].includes(device);
  const controls={index,device,active:p1||players===2,magic:p1?'Right Shift / L':'Left Shift',run:p1?'R':'F'};
  if(device==='keypad')Object.assign(controls,{label:'Keypad · numeric keypad',movement:'Num 7 8 9 / 4 · 6 / 1 2 3',attack:'Num 5',jump:'Insert'});
  else if(device==='keyboard')Object.assign(controls,{label:'Keyboard · letter keys',movement:'Q W E / A · D / Z X C',attack:'S',jump:'Tab'});
  else if(device==='mouse')Object.assign(controls,{label:'Mouse',movement:'Move the mouse over the game; Capture mouse is in Options.',attack:'left mouse button',jump:'right mouse button'});
  else Object.assign(controls,{label:device==='joystick2'?'Joystick 2 · second gamepad':'Joystick 1 · first gamepad',movement:'Move the stick; calibration is in Options.',attack:'button 1',jump:'button 2'});
  if(p1&&keyboard){controls.movement+='; also arrow keys';controls.attack+=' / J';controls.jump+=' / K';}
  if(p1&&device==='keypad'&&players===1)controls.movement+=' or WASD';
  controls.runNote=keyboard?'Quickly press the same horizontal direction twice, then hold the second press.':device==='mouse'?'Move the mouse faster horizontally while facing the same direction.':'Push the stick farther left/right in the direction of travel.';
  return controls;
}

export function createControlsHelp({getSettings,onOpen=()=>null,onClose=()=>{}}) {
  const dialog=document.createElement('dialog');dialog.className='controls-dialog';dialog.setAttribute('aria-labelledby','controls-title');
  dialog.innerHTML=`<div class="controls-card"><header class="controls-heading"><div><p class="controls-eyebrow">GOLDEN AXE</p><h2 id="controls-title">Controls and combat combos</h2></div><button data-controls-close class="controls-close" aria-label="Close the controls guide">Close <span aria-hidden="true">×</span></button></header><div class="controls-body" tabindex="0"><p class="controls-intro">These controls follow your current Options settings. Moving up and down changes your depth on the playfield; it does not make your hero crouch.</p><div class="controls-players"></div><section><h3>On-foot combat combos</h3><p>ATTACK and JUMP below mean the selected player's buttons listed above. Each new attack requires a new press; holding the button does not produce an automatic combo. Key examples use the default P1 Keypad and P2 Keyboard settings. For other devices, use the corresponding buttons in your player card.</p><dl class="controls-combos"><dt>Run</dt><dd>Quickly press the same left/right direction twice and hold the second press. In the web version, you can also hold <kbd>R</kbd> (player 1) or <kbd>F</kbd> (player 2) while moving.</dd><dt>Running jump</dt><dd>Start running, then press JUMP. P1: <kbd>R</kbd> + <kbd>→</kbd> + <kbd>K</kbd>. P2 with the default Keyboard: <kbd>F</kbd> + <kbd>D</kbd> + <kbd>Tab</kbd>. This is the original higher jump, needed for the first high step in stage 4.</dd><dt>Running attack</dt><dd>Press ATTACK while running. Your hero performs a shoulder charge, kick, or headbutt. P1: <kbd>R</kbd> + direction + <kbd>J</kbd>; P2 with the default Keyboard: <kbd>F</kbd> + direction + <kbd>S</kbd>.</dd><dt>Special attack</dt><dd>While standing or walking, press ATTACK and JUMP together. P1: <kbd>J</kbd> + <kbd>K</kbd>; P2 with the default Keyboard: <kbd>S</kbd> + <kbd>Tab</kbd>.</dd><dt>Air attack</dt><dd>Press JUMP, then shortly afterward press ATTACK. You can also attack in the air after a running jump. The attack and its reach depend on your hero and the phase of the jump.</dd><dt>Potion thieves</dt><dd>Thieves drop one item per successful hit while they still carry stock; empty thieves flee.</dd><dt>Combos and close attacks</dt><dd>Repeatedly press ATTACK near an enemy. The original rules choose combo finishers and close-range attacks according to the distance and the enemy's state.</dd></dl><p><strong>Mounting:</strong> Knock off any enemy rider, then walk close to a waiting animal on the same ground level. You do not need to jump. Escaping animals can no longer be mounted.</p><p>While riding, use the same directions, ATTACK, and JUMP. On-foot combos do not apply to mounted attacks. <strong>Mounted attacks:</strong> The stage 2 fireball dragon shoots above a low, standing potion thief. Start running first, then press ATTACK for a running body strike instead of a shot. P1: hold <kbd>R</kbd> + direction until running, then press <kbd>J</kbd>; P2 with the default Keyboard: hold <kbd>F</kbd> + direction, then press <kbd>S</kbd>. You can also start the run with the original double-tap. Flame breath and a running strike have different reach from a fireball. <strong>Dismounting:</strong> Using available magic while the mount is on the ground dismounts your hero; JUMP keeps you riding. Magic requires collected potion bottles.</p></section><section><h3>Phone and tablet</h3><p>Touch controls operate player 1. The direction buttons move in both axes. Tap the ATTACK pad to attack, swipe up to jump, or swipe down to move down the playfield. Separate JUMP and MAGIC buttons let you combine actions. For a running jump, hold <strong>RUN + direction</strong>, then tap <strong>JUMP</strong>. Two independent touch controllers on one phone are not currently supported.</p></section><section><h3>Pause, audio, and testing cheats</h3><dl class="controls-combos"><dt>Pause</dt><dd><kbd>Space</kbd> or <kbd>Esc</kbd>, or the on-screen Ⅱ button. Inside this guide, <kbd>Esc</kbd> closes only the guide.</dd><dt>Audio</dt><dd><kbd>F2</kbd> toggles sound effects, <kbd>F3</kbd> toggles music. The ♪ button mutes or unmutes all audio. Remastered music and sound effects are the defaults. <kbd>MUSIC</kbd> switches the music edition; use the Sound effects button in Options or Pause to select the effects edition. Tracks are downloaded when first needed.</dd><dt>Cheats</dt><dd>Type commands directly; they are case-insensitive and do not need Shift. <kbd>L</kbd> waits up to 0.3 seconds to distinguish magic from <kbd>LEVEL</kbd>; <kbd>Right Shift</kbd> casts immediately. Matching cheat letters are kept out of combat input. Type <kbd>HD</kbd> to switch graphics, <kbd>IDDQD</kbd> for invulnerability, <kbd>MAP</kbd> for the full map and click-to-move, or <kbd>LEVEL</kbd> to select an original level. On a phone, use the buttons in Pause. Cheats are ignored while this guide is open.</dd></dl><p class="controls-origin">Original controls and combos are preserved. Arrow keys/J/K/L for player 1, R/F run shortcuts, touch controls, and cheats are additions to the web version. This guide does not add new combat mechanics.</p></section></div></div>`;
  document.querySelector('#game-shell').append(dialog);
  let saved=null,restoreFocus=null,disposed=false;
  function render(){const settings=getSettings(),players=settings.players===2?2:1;dialog.querySelector('.controls-players').replaceChildren(...[0,1].map(index=>{const row=playerControls(index,settings.devices?.[index]||(index?'keyboard':'keypad'),players),section=document.createElement('section');section.className='controls-player';section.dataset.helpPlayer=String(index);const title=document.createElement('h3');title.textContent=`Player ${index+1}${row.active?'':' · for two-player mode'}`;const label=document.createElement('p');label.className='controls-device';label.textContent=row.label;const list=document.createElement('dl');for(const [name,value]of[['Move',row.movement],['Attack',row.attack],['Jump',row.jump],['Magic',row.magic],['Run shortcut',`${row.run} + left/right`]]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=name;dd.textContent=value;list.append(dt,dd);}const note=document.createElement('p');note.className='controls-device-note';note.textContent=row.runNote;section.append(title,label,list,note);return section;}));}
  function open(){if(disposed)return false;if(dialog.open)return true;render();restoreFocus=document.activeElement;saved=onOpen();dialog.showModal();dialog.querySelector('.controls-body').scrollTop=0;dialog.querySelector('[data-controls-close]').focus({preventScroll:true});return true;}
  function close({restore=true}={}){if(!dialog.open)return;dialog.close();const snapshot=saved;saved=null;const target=onClose(snapshot,{restore})||restoreFocus;if(restore&&target?.isConnected)target.focus({preventScroll:true});}
  dialog.querySelector('[data-controls-close]').addEventListener('click',()=>close());
  dialog.addEventListener('cancel',event=>{event.preventDefault();close();});
  dialog.addEventListener('keydown',event=>{
    event.stopPropagation();
    if(['F2','F3','F4','F5'].includes(event.code))event.preventDefault();
    if(event.code==='Escape'){event.preventDefault();close();return;}
    if(event.code==='Tab'){
      const items=[...dialog.querySelectorAll('button,[tabindex="0"]')],first=items[0],last=items.at(-1);
      if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}
      else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}
    }
  });
  dialog.addEventListener('keyup',event=>event.stopPropagation());
  const buttons=[...document.querySelectorAll('[data-open-controls]')],click=()=>open();for(const button of buttons)button.addEventListener('click',click);
  return{open,close,get isOpen(){return dialog.open;},dispose(){if(disposed)return;close({restore:false});disposed=true;for(const button of buttons)button.removeEventListener('click',click);dialog.remove();}};
}
